  "content": "1|import type { DesignerVersionSummary } from '../../../shared/api/queries/component-designer';
2|import type { DesignerHandoffPayload } from '../../../shared/api/contracts/ai/agentTypes';
3|import { normalizeDesignerComponentName } from '../utils/componentName';
4|import { normalizeComponentFolder } from '../utils/componentFolder';
5|import {
6|  buildComponentDesignerNewRelativePath,
7|  CLIENT_COMPONENT_LIST_SEGMENT,
8|} from '../componentDesignerRoute';
9|
10|const DEFAULT_DRAFT_FOLDER = 'general';
11|
12|export function buildDesignerComponentPath(folder: string, componentName: string): string {
13|  const normalizedFolder = normalizeComponentFolder(folder || DEFAULT_DRAFT_FOLDER);
14|  const normalizedName = normalizeDesignerComponentName(componentName);
15|  return `${normalizedFolder}/${normalizedName}`;
16|}
17|
18|export function parseDesignerComponentPath(value: string): { folder: string; componentName: string } | null {
19|  const trimmed = value.trim().replace(/^\/+/, '');
20|  const slashIndex = trimmed.indexOf('/');
21|  if (slashIndex <= 0) {
22|    return null;
23|  }
24|
25|  const folder = trimmed.slice(0, slashIndex).trim();
26|  const componentName = trimmed.slice(slashIndex + 1).trim();
27|  if (!folder || !componentName) {
28|    return null;
29|  }
30|
31|  return { folder, componentName };
32|}
33|
34|export function resolveDesignerDraftIdFromComponentPath(
35|  drafts: readonly DesignerVersionSummary[],
36|  componentPath: string,
37|): string | null {
38|  const parsed = parseDesignerComponentPath(componentPath);
39|  if (!parsed) {
40|    return null;
41|  }
42|
43|  const normalizedFolder = normalizeComponentFolder(parsed.folder);
44|  const normalizedName = normalizeDesignerComponentName(parsed.componentName);
45|
46|  const match = drafts.find(
47|    (draft) => normalizeComponentFolder(draft.folder || DEFAULT_DRAFT_FOLDER) === normalizedFolder
48|      && normalizeDesignerComponentName(draft.name) === normalizedName,
49|  );
50|
51|  return match?.id ?? null;
52|}
