54|export function buildComponentDesignerDraftUrl(
55|  mountPathPrefix: string,
56|  folder: string,
57|  componentName: string,
58|): string {
59|  const normalizedPrefix = mountPathPrefix.replace(/\/+$/, '') || '';
60|  const slug = buildDesignerComponentPath(folder, componentName);
61|  return `${normalizedPrefix}/${CLIENT_COMPONENT_LIST_SEGMENT}/${slug}`;
62|}
63|
64|export const DESIGNER_NEW_DRAFT_PARAM = 'new';
65|
66|export function isDesignerNewDraftSearchParam(value: string | null | undefined): boolean {
67|  return value === '1' || value === 'true';
68|}
69|
70|export function buildComponentDesignerNewUrl(mountPathPrefix: string): string {
71|  const normalizedPrefix = mountPathPrefix.replace(/\/+$/, '') || '';
72|  return `${normalizedPrefix}/${buildComponentDesignerNewRelativePath()}`;
73|}
74|
75|/** Studio mount prefix from a portal pathname (`/us/studio/...` → `/us/studio`). */
76|export function resolveStudioMountPathPrefix(pathname: string): string {
77|  const normalized = pathname.replace(/\/+$/, '') || '/';
78|  const match = normalized.match(/^(\/[^/]+\/studio|\/studio)(?=\/|$)/);
79|  return match?.[1] ?? '/studio';
80|}
81|
82|/** Deep link for AppEndoo / apply handoff into Component Designer. */
83|export function buildDesignerHandoffUrl(
84|  mountPathPrefix: string,
85|  handoff: Pick<DesignerHandoffPayload, 'layoutId' | 'componentPath'>,
86|): string {
87|  const normalizedPrefix = resolveStudioMountPathPrefix(mountPathPrefix).replace(/\/+$/, '') || '/studio';
88|  const componentPath = handoff.componentPath?.trim();
89|  if (componentPath) {
90|    const slug = componentPath.replace(/^\/+/, '');
91|    return `${normalizedPrefix}/${CLIENT_COMPONENT_LIST_SEGMENT}/${slug}`;
92|  }
93|
94|  const params = new URLSearchParams();
95|  params.set('load', handoff.layoutId.trim());
96|  return `${normalizedPrefix}/${CLIENT_COMPONENT_LIST_SEGMENT}?${params.toString()}`;
97|}
